/* Browser code contains no provider secrets. All billing requests go to our server. */
window.WardogsBilling={
  async account(target,escape){
    const response=await fetch('/api/session');if(!response.ok)throw Error('Account service unavailable');const session=await response.json();
    const configResponse=await fetch('/api/billing/config');if(!configResponse.ok)throw Error('Billing service unavailable');const config=await configResponse.json();
    if(!target.isConnected)return;
    const status='<div class="notice"><strong>PAYPAL SANDBOX</strong> · Test transactions only. No real money is charged. Whitelist, Reserved access and Discord roles are not connected.</div>';
    if(!session.user){target.innerHTML=status+`<div class="panel"><h2>Start with Discord.</h2><p>Sign in to link your community identity before testing a membership.</p>${session.loginAvailable?'<a class="button primary" href="/auth/discord">Sign in with Discord ↗</a>':'<p class="notice">Discord sign-in is being configured. Please check back soon.</p>'}</div>`;return;}
    const billingResponse=await fetch('/api/billing/subscriptions');if(!billingResponse.ok)throw Error('Could not load subscriptions');const data=await billingResponse.json();
    // A return from PayPal requests verification; it never activates membership by itself.
    if(new URLSearchParams(location.search).get('checkout')==='returned'){
      history.replaceState(null,'',location.pathname+'#account');
      for(const item of data.subscriptions)await fetch('/api/billing/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.id})});
      return window.WardogsBilling.account(target,escape);
    }
    if(!target.isConnected)return;
    target.innerHTML=status+`<div class="panel"><p class="eyebrow">DISCORD ACCOUNT LINKED</p><h2>Welcome, ${escape(session.user.displayName)}.</h2><p>Discord ID: ${escape(session.user.discordId)}</p><button id="sign-out" class="button secondary">Sign out</button></div>${!config.ready?'<p class="notice">PayPal sandbox setup is incomplete. Checkout stays closed until test credentials, plans and the HTTPS webhook are configured.</p>':''}<div id="billing-result" role="status"></div>${data.subscriptions.length?data.subscriptions.map(item=>`<article class="panel"><p class="eyebrow">SANDBOX DONATION SUBSCRIPTION</p><h2>${escape(item.name)}</h2><dl class="facts"><div><dt>Price</dt><dd>${escape(item.amount)} USD every ${escape(item.billingLabel)}</dd></div><div><dt>Servers</dt><dd>${item.servers.map(escape).join(' + ')}</dd></div><div><dt>PayPal status</dt><dd>${escape(item.status)}</dd></div><div><dt>Next billing</dt><dd>${escape(item.nextBilling||'Not yet confirmed')}</dd></div><div><dt>Verified period end</dt><dd>${escape(item.paidUntil||'Not yet confirmed')}</dd></div><div><dt>Reserved access / Discord roles</dt><dd>Not connected</dd></div></dl>${item.reviewRequired?'<p class="notice">A refund or reversal requires staff review. No access is granted by this preview.</p>':''}<div class="actions" style="margin-top:20px"><button class="button secondary" data-billing-action="refresh" data-subscription="${escape(item.id)}">Check PayPal status</button>${!['CANCELLED','EXPIRED'].includes(item.status)?`<button class="button secondary" data-billing-action="cancel" data-subscription="${escape(item.id)}">Cancel sandbox subscription</button>`:''}<a class="button secondary" href="https://www.sandbox.paypal.com/myaccount/autopay/" target="_blank" rel="noopener noreferrer">Manage sandbox payments ↗</a></div></article>`).join(''):'<div class="panel"><h3>No paid subscription.</h3><p>Your community account is free. You have not reserved a slot by signing in.</p><a class="textlink" href="#memberships">Explore sandbox memberships ↗</a></div>'}`;
    target.querySelector('#sign-out').addEventListener('click',async e=>{e.target.disabled=true;const r=await fetch('/api/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(r.ok)loadAccount();else{e.target.disabled=false;e.target.textContent='Sign-out failed · retry';}});
    target.querySelectorAll('[data-billing-action]').forEach(button=>button.addEventListener('click',async()=>{
      const action=button.dataset.billingAction;if(action==='cancel'&&!confirm('Cancel this SANDBOX subscription and stop future test renewals?'))return;
      button.disabled=true;try{const r=await fetch('/api/billing/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:button.dataset.subscription})});const result=await r.json();if(!r.ok)throw Error(result.error);await loadAccount();}catch(error){button.disabled=false;target.querySelector('#billing-result').textContent=error.message||'The request failed. Please retry.';}
    }));
  }
};
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-plan]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();
  const plan=D.plans.find(p=>p.id===button.dataset.offer),months=Number(button.dataset.months);if(!plan||![1,3,6].includes(months))return;
  const variantId=plan.id+'-'+months+'m';
  const server=document.querySelector('#membership-server-'+plan.id)?.value||'za-01';
  const dialog=document.querySelector('#notice'),body=document.querySelector('#notice-body');
  body.innerHTML='<h2>Checking sandbox checkout…</h2>';dialog.showModal();
  try{
    const[r,s]=await Promise.all([fetch('/api/billing/config'),fetch('/api/session')]);if(!r.ok||!s.ok)throw Error('Use the local site launcher to access sandbox billing.');const[config,session]=await Promise.all([r.json(),s.json()]);
    if(!config.ready||!session.loginAvailable){body.innerHTML='<p class="eyebrow">PAYPAL / SANDBOX ONLY</p><h2>Checkout is being configured.</h2><p>Test credentials, Discord sign-in and the public HTTPS webhook must be configured before a test subscription can start. No real payments are enabled.</p>';return;}
    if(!session.user){body.innerHTML='<h2>Link your Discord first.</h2><p>Your account lets us associate the test subscription with you.</p><a class="button primary" href="/auth/discord">Sign in with Discord ↗</a>';return;}
    body.innerHTML=`<p class="eyebrow">DONATION SUBSCRIPTION / PAYPAL SANDBOX</p><h2>${safe(plan.name)}</h2><p>$${money(plan.prices[months])} USD charged in full every ${periodText(months)} until cancelled. Coverage: ${plan.servers===2?'Server 01 and Server 02':server==='za-01'?'Server 01':'Server 02'}.</p><p>Benefit: ${plan.benefit==='whitelist'?'Whitelist queue priority when full.':'Reserved capacity held for eligible members.'} Community support is voluntary; this selection is a recurring donation subscription with the stated benefit.</p><p>Use a PayPal sandbox buyer account. This creates a test subscription only; access benefits and Discord roles are not activated.</p><label style="display:block;margin:20px 0"><input id="sandbox-consent" type="checkbox"> I understand the full amount renews every ${periodText(months)} and this is sandbox testing, with no real charges or server perks.</label><button id="sandbox-checkout" class="button primary" disabled>Continue to PayPal sandbox ↗</button><p id="checkout-error" role="status" style="margin-top:16px"></p>`;
    const consent=body.querySelector('#sandbox-consent'),submit=body.querySelector('#sandbox-checkout');consent.addEventListener('change',()=>submit.disabled=!consent.checked);
    submit.addEventListener('click',async()=>{submit.disabled=true;try{const response=await fetch('/api/billing/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan:variantId,server,acceptedSandboxTerms:true})});const result=await response.json();if(!response.ok)throw Error(result.error);if(new URL(result.approvalUrl).origin!=='https://www.sandbox.paypal.com')throw Error('Unexpected payment destination.');location.assign(result.approvalUrl);}catch(error){body.querySelector('#checkout-error').textContent=error.message||'Checkout could not start.';submit.disabled=!consent.checked;}});
  }catch(error){body.textContent=error.message||'Sandbox checkout is unavailable.';}
},true);
